{"type":"javascript","code":"// Rain Night: Top Floor - Murder-Mystery GM state machine (English edition)
const STATE = 'case_state_en.json';
const DASH = 'case_dashboard_en.html';
const SUSPECTS = ['Elena Su', 'Marcus Chen', 'Henry He'];
const KILLER = 'Marcus Chen';
const ROLES = { 'Elena Su': 'wife', 'Marcus Chen': 'vice president', 'Henry He': 'personal secretary' };

const ALIASES = {
  'elena su': 'Elena Su', 'su wanqing': 'Elena Su', '苏晚晴': 'Elena Su', 'elena': 'Elena Su', 'su': 'Elena Su', 'wife': 'Elena Su', 'the wife': 'Elena Su', 'mrs su': 'Elena Su', 'mrs. su': 'Elena Su',
  'marcus chen': 'Marcus Chen', 'chen mo': 'Marcus Chen', '陈默': 'Marcus Chen', 'marcus': 'Marcus Chen', 'chen': 'Marcus Chen', 'mr chen': 'Marcus Chen', 'mr. chen': 'Marcus Chen', 'vp': 'Marcus Chen', 'vice president': 'Marcus Chen',
  'henry he': 'Henry He', 'he yu': 'Henry He', '何雨': 'Henry He', 'henry': 'Henry He', 'he': 'Henry He', 'secretary': 'Henry He', 'mr he': 'Henry He', 'mr. he': 'Henry He'
};
function normName(n) {
  const raw = String(n == null ? '' : n).trim();
  const k = raw.toLowerCase().replace(/\s+/g, ' ');
  if (ALIASES[k]) return ALIASES[k];
  for (const s of SUSPECTS) if (s.toLowerCase() === k) return s;
  return raw;
}

const CANON_CLUES = [
  { id: 'door_2115', text: 'Marcus Chen cannot explain the smart-home log: the study door opened once at 21:15.', sources: ['Marcus Chen', 'Henry He'] },
  { id: 'balcony_cam', text: 'The balcony camera was broken that night; it cannot prove Marcus Chen was on the balcony.', sources: ['Marcus Chen', 'Henry He'] },
  { id: 'henry_witness', text: 'Henry He was in the kitchen at 21:10 and saw someone leave the study.', sources: ['Henry He'] },
  { id: 'su_argument', text: 'Elena Su had a heated phone argument with Victor Lin at 15:00.', sources: ['Elena Su'] },
  { id: 'su_divorce', text: 'Elena Su is preparing for divorce and holds a draft of the premarital property agreement.', sources: ['Elena Su'] },
  { id: 'su_balcony', text: 'Elena Su stayed on the balcony after 21:00; the corridor cameras corroborate.', sources: ['Elena Su', 'Henry He'] },
  { id: 'embezzlement', text: 'CORE MOTIVE: Marcus Chen embezzled 80 million; Victor Lin discovered it and was going to report him.', sources: ['Marcus Chen', 'Henry He'] }
];
function normText(t) { return String(t == null ? '' : t).toLowerCase().replace(/[^a-z0-9:\u4e00-\u9fff]+/g, ' ').trim(); }
function findClue(text) {
  const k = normText(text);
  for (const c of CANON_CLUES) if (normText(c.text) === k) return c;
  if (/21:15/.test(k) && /(door|lock)/.test(k)) return CANON_CLUES[0];
  if (/balcony camera/.test(k) && /(broken|broke|fail|dead)/.test(k)) return CANON_CLUES[1];
  if (/kitchen/.test(k) && /21:10/.test(k)) return CANON_CLUES[2];
  if (/15:00/.test(k) && /(argument|fight|argued)/.test(k)) return CANON_CLUES[3];
  if (/divorce/.test(k) && /(draft|agreement|premarital)/.test(k)) return CANON_CLUES[4];
  if (/(elena|su)/.test(k) && /balcony/.test(k) && /(camera|corrobora|21:00)/.test(k)) return CANON_CLUES[5];
  if (/(80 million|eighty million|embezzl|siphon)/.test(k)) return CANON_CLUES[6];
  return null;
}

function fresh() {
  return { version: 1, phase: 'investigation', round: 1, maxRounds: 5, asked: {}, clues: [], suspicion: { 'Elena Su': 40, 'Marcus Chen': 30, 'Henry He': 30 }, accusation: null, winner: null };
}
async function load() {
  try { const s = JSON.parse(await $read(STATE)); if (s && s.version === 1 && Array.isArray(s.clues)) return s; } catch (e) {}
  return fresh();
}
async function persist(s) { await $write(STATE, JSON.stringify(s, null, 2)); return s; }
function sum(s) {
  return { phase: s.phase, round: s.round, maxRounds: s.maxRounds, asked: s.asked, clues: s.clues, suspicion: s.suspicion, accusation: s.accusation, winner: s.winner, remainingRounds: s.phase === 'investigation' ? s.maxRounds - s.round + 1 : 0 };
}

const TRUTH = [
  'The killer is Marcus Chen, Vice President of Linzhou Technologies.',
  'He had embezzled 80 million of company funds. Victor Lin discovered the fraud and was preparing to report him.',
  '21:05 - Marcus poured cyanide into Victor\'s whisky in the study.',
  '21:10 - Marcus left the study. Henry He, making tea in the kitchen, saw a figure come out of the study.',
  '21:15 - Marcus slipped back into the study and took the USB drive holding the siphoned-funds records. The smart-home system logged the study door opening once.',
  '21:16 - Marcus left the study again. He claimed he "never went back" - the 21:15 door log and the broken balcony camera destroyed that lie.',
  '21:30 - Victor Lin was found dead. Cyanide in the whisky glass. No sign of intruders.',
  'Elena Su\'s 15:00 argument and her pending divorce made her a red herring: after 21:00 she was on the balcony the whole time, corroborated by the corridor cameras and Henry He.'
];

function esc(t) { return String(t == null ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
function colorFor(v) { return v >= 70 ? '#e05252' : v >= 45 ? '#e0a13c' : '#4f8f6d'; }
function makeHtml(s) {
  const badge = s.phase === 'investigation' ? '<span class="badge investigating">UNDER INVESTIGATION</span>'
    : s.phase === 'won' ? '<span class="badge won">CASE SOLVED - VICTORY</span>'
    : '<span class="badge lost">CASE CLOSED - FAILED</span>';
  const suspectRows = SUSPECTS.map(n => {
    const askedMark = s.phase === 'investigation' ? (s.asked[n] === s.round ? 'answered this round' : 'not yet answered this round') : 'case closed';
    return '<div class="suspect"><div class="sname">' + esc(n) + ' <span class="role">- ' + ROLES[n] + '</span></div><div class="srow"><div class="bar"><div class="fill" style="width:' + (s.suspicion[n] || 0) + '%;background:' + colorFor(s.suspicion[n] || 0) + '"></div></div><span class="sval">' + (s.suspicion[n] || 0) + '</span></div><div class="sasked">' + askedMark + '</div></div>';
  }).join('');
  const clueItems = s.clues.length
    ? s.clues.map((c, i) => '<li><b>Clue ' + (i + 1) + '</b> - ' + esc(c.text) + ' <span class="meta">(source: ' + esc(c.source) + ' - round ' + c.round + ')</span></li>').join('')
    : '<li class="empty">No clues registered yet.</li>';
  const progress = s.phase === 'investigation'
    ? 'Round ' + s.round + ' / ' + s.maxRounds + ' - ' + (s.maxRounds - s.round + 1) + ' round(s) remaining'
    : 'Round ' + s.round + ' / ' + s.maxRounds + ' - case closed';
  const verdict = s.phase === 'won' ? 'Correct - the killer was ' + KILLER : 'Incorrect - the killer was ' + KILLER;
  const truthBlock = s.phase !== 'investigation'
    ? '<section class="truth"><h2>Full Truth</h2><p>Accusation: <b>' + esc(s.accusation || '-') + '</b> - Verdict: <b>' + verdict + '</b></p><ol>' + TRUTH.map(t => '<li>' + esc(t) + '</li>').join('') + '</ol></section>'
    : '';
  return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rain Night: Top Floor - Case Board</title><style>'
    + 'body{margin:0;background:#101418;color:#dfe6ec;font-family:Segoe UI,Arial,sans-serif;padding:28px}'
    + '.wrap{max-width:760px;margin:0 auto}'
    + 'header{border-bottom:2px solid #2c3540;padding-bottom:14px;margin-bottom:20px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px}'
    + 'h1{font-size:20px;letter-spacing:2px;margin:0;color:#f0f4f8}'
    + '.sub{color:#8fa0b0;font-size:12px;margin-top:4px}'
    + '.badge{padding:6px 12px;border-radius:20px;font-size:12px;font-weight:600;letter-spacing:1px;white-space:nowrap}'
    + '.investigating{background:#1d3a5f;color:#8ec4ff}.won{background:#14432a;color:#7fe0a8}.lost{background:#4a1d22;color:#ff9d9d}'
    + 'section{background:#171d24;border:1px solid #2c3540;border-radius:10px;padding:16px;margin-bottom:16px}'
    + 'h2{font-size:13px;letter-spacing:2px;color:#8fa0b0;margin:0 0 12px;text-transform:uppercase}'
    + '.roundline{font-size:15px}'
    + '.suspect{margin-bottom:12px}.sname{font-weight:600;font-size:14px}.role{color:#8fa0b0;font-weight:400;font-size:12px}'
    + '.srow{display:flex;align-items:center;gap:10px;margin-top:6px}'
    + '.bar{flex:1;height:10px;background:#232b34;border-radius:5px;overflow:hidden}.fill{height:100%;border-radius:5px}'
    + '.sval{width:28px;text-align:right;font-variant-numeric:tabular-nums}.sasked{font-size:11px;color:#8fa0b0;margin-top:2px}'
    + 'ul,ol{margin:0;padding-left:20px;line-height:1.7}.meta{color:#8fa0b0;font-size:12px}.empty{color:#8fa0b0}'
    + '.truth{border-color:#7a5b2b;background:#1c1a14}.truth h2{color:#e0c37c}'
    + 'footer{color:#5c6b7a;font-size:11px;text-align:center;margin-top:8px}'
    + '</style></head><body><div class="wrap">'
    + '<header><div><h1>RAIN NIGHT: TOP FLOOR</h1><div class="sub">Aster House - 27th-floor penthouse - Case Board</div></div>' + badge + '</header>'
    + '<section><h2>Progress</h2><div class="roundline">' + progress + '</div></section>'
    + '<section><h2>Suspicion</h2>' + suspectRows + '</section>'
    + '<section><h2>Clues (' + s.clues.length + ' / 7 core)</h2><ul>' + clueItems + '</ul></section>'
    + truthBlock
    + '<footer>Victim: Victor Lin - cyanide in the whisky - no sign of intruders</footer>'
    + '</div></body></html>';
}

const s = await load();
const action = String(input.action == null ? 'state' : input.action).toLowerCase().trim();

if (action === 'init') {
  const f = fresh(); await persist(f);
  await $write(DASH, makeHtml(f));
  return { ok: true, action: 'init', dashboard: DASH, state: sum(f), instruction: 'Call file_display on the dashboard path to open the case board, then deliver the full opening (case background + how to play).' };
}
if (action === 'mark_asked') {
  const name = normName(input.name);
  if (!SUSPECTS.includes(name)) return { ok: false, error: 'Unknown suspect: ' + input.name };
  if (s.phase !== 'investigation') return { ok: false, error: 'The case is already closed.', state: sum(s) };
  if (s.asked[name] === s.round) return { ok: true, name, alreadyAnswered: true, state: sum(s), instruction: 'That suspect already answered this round; tell the player briefly and do NOT have them answer again.' };
  s.asked[name] = s.round; await persist(s);
  return { ok: true, name, alreadyAnswered: false, state: sum(s), instruction: 'Let that suspect answer; if a new clue appears, register it via add_clue, then run dashboard + file_display.' };
}
if (action === 'add_clue') {
  const canon = findClue(input.text);
  const text = canon ? canon.text : String(input.text || '').trim();
  if (!text) return { ok: false, error: 'Clue text is empty.' };
  if (s.clues.some(c => normText(c.text) === normText(text))) return { ok: true, added: false, clue: text, state: sum(s), instruction: 'Clue already on the board; still run dashboard + file_display to refresh it.' };
  s.clues.push({ id: canon ? canon.id : 'custom', text, source: normName(input.source) || 'Unknown', round: s.round });
  await persist(s);
  return { ok: true, added: true, clue: text, state: sum(s), instruction: 'Run dashboard + file_display to update the board and note the new clue in one line.' };
}
if (action === 'next_round') {
  if (s.phase !== 'investigation') return { ok: false, error: 'The case is already closed.', state: sum(s) };
  if (s.round >= s.maxRounds) {
    s.phase = 'lost'; s.winner = null; await persist(s);
    await $write(DASH, makeHtml(s));
    return { ok: true, outcome: 'lost', reason: 'Rounds ran out without an accusation.', dashboard: DASH, truth: TRUTH, state: sum(s), instruction: 'Call file_display on the dashboard path, declare the failure, and reveal the full truth.' };
  }
  s.round += 1; s.asked = {}; await persist(s);
  return { ok: true, round: s.round, state: sum(s), instruction: 'Update suspicion via set_suspicion if the case warrants it, then run dashboard + file_display and announce the new round.' };
}
if (action === 'set_suspicion') {
  const name = normName(input.name);
  if (!SUSPECTS.includes(name)) return { ok: false, error: 'Unknown suspect: ' + input.name };
  let v;
  if (typeof input.value === 'number') v = input.value;
  else if (typeof input.delta === 'number') v = (s.suspicion[name] || 0) + input.delta;
  else return { ok: false, error: 'Provide value (0-100) or delta.' };
  s.suspicion[name] = Math.max(0, Math.min(100, Math.round(v)));
  await persist(s);
  return { ok: true, name, suspicion: s.suspicion[name], state: sum(s), instruction: 'Run dashboard + file_display to update the board.' };
}
if (action === 'accuse') {
  const name = normName(input.name);
  if (!SUSPECTS.includes(name)) return { ok: false, error: 'Unknown suspect: ' + input.name };
  if (s.phase !== 'investigation') return { ok: false, error: 'The case is already closed.', state: sum(s) };
  s.accusation = name;
  s.phase = name === KILLER ? 'won' : 'lost';
  s.winner = s.phase === 'won' ? 'player' : null;
  await persist(s);
  await $write(DASH, makeHtml(s));
  return { ok: true, won: s.phase === 'won', accused: name, dashboard: DASH, truth: TRUTH, state: sum(s), instruction: 'Call file_display on the dashboard path, declare the verdict, and reveal the full truth plus a clue recap.' };
}
if (action === 'dashboard') {
  await $write(DASH, makeHtml(s));
  return { ok: true, dashboard: DASH, state: sum(s), instruction: 'Call file_display on the dashboard path to open the case board, then note the change in one line.' };
}
return { ok: true, state: sum(s), actions: ['init', 'mark_asked', 'add_clue', 'next_round', 'set_suspicion', 'accuse', 'dashboard', 'state'] };
"}
